import {createHash,randomUUID} from 'node:crypto';
import {mkdir,readFile,rm,open,link} from 'node:fs/promises';
import {join} from 'node:path';
import type {FileStoragePort} from '../application/platform-core.application-service.js';

/** Trusted binary storage adapter. Keys are generated by the server, including stable upload identities. */
export class LocalFileStorage implements FileStoragePort {
  constructor(private readonly root=process.env.ELHAFEZ_FILE_STORAGE_ROOT??'/var/lib/elhafez/files'){}
  async put(input:{content:Uint8Array;contentType:string}){return this.putOnce(randomUUID(),input);}
  async putOnce(key:string,input:{content:Uint8Array;contentType:string}){
    const target=this.path(key);await mkdir(this.root,{recursive:true,mode:0o700});const temporary=this.path(randomUUID()),handle=await open(temporary,'wx',0o600);
    try{try{await handle.writeFile(input.content);await handle.sync();}finally{await handle.close();}
      try{await link(temporary,target);}catch(error){if(!(error&&typeof error==='object'&&'code' in error&&error.code==='EEXIST'))throw error;}
      const content=await this.get(key),checksum=createHash('sha256').update(content).digest('hex');if(!Buffer.from(content).equals(input.content))throw new Error('stable storage identity contains different bytes');
      const directory=await open(this.root,'r');try{await directory.sync();}finally{await directory.close();}return{key,size:content.byteLength,checksum};
    }finally{await rm(temporary,{force:true});}
  }
  async get(key:string){return new Uint8Array(await readFile(this.path(key)))}
  async delete(key:string){await rm(this.path(key),{force:true})}
  private path(key:string){if(!/^[0-9a-f-]{36}$/.test(key))throw new Error('invalid storage key');return join(this.root,key)}
}
